// n8n Code Node: Extract URLs with specific format
// FIXED: Preserve original post data while adding URL information
// FIXED: Maintain same number of output items as input items

// Define media file extensions
const imageExtensions = ['jpg', 'jpeg', 'png', 'gif', 'bmp', 'svg', 'webp', 'ico'];
const videoExtensions = ['mp4', 'avi', 'mov', 'wmv', 'flv', 'webm', 'mkv', 'm4v', 'mp3', 'wav', 'ogg', 'aac', 'flac', 'm4a', 'wma'];

// URL regex pattern
const urlRegex = /https?:\/\/[^\s<>"{}|\\^`[\]]+/gi;

// Function to determine URL type
function getUrlType(url) {
  const lowerUrl = url.toLowerCase();

  // Check for image extensions
  if (imageExtensions.some(ext => lowerUrl.includes(`.${ext}`))) {
    return 'image';
  }

  // Check for video/audio extensions
  if (videoExtensions.some(ext => lowerUrl.includes(`.${ext}`))) {
    return 'video';
  }

  // Default to page for all other URLs
  return 'page';
}

// Function to clean URL (remove trailing punctuation)
function cleanUrl(url) {
  return url.replace(/[.,;:!?)\]}>]+$/, '');
}

// Process input data - maintain same number of items as input
const results = [];

for (const item of $input.all()) {
  const text = item.json.text;

  // Initialize result item with all original data
  const resultItem = {
    json: {
      // Preserve all original post data
      ...item.json,
      // Initialize URL fields as null
      url_text_type: null,
      url_text: null
    }
  };

  // Only process if text exists and is a string
  if (text && typeof text === 'string') {
    // Extract all URLs from text
    const foundUrls = text.match(urlRegex) || [];

    if (foundUrls.length > 0) {
      // Take the first valid URL found
      for (let url of foundUrls) {
        // Clean the URL
        url = cleanUrl(url);

        // Only include valid web URLs (starts with http/https)
        if (url.startsWith('http://') || url.startsWith('https://')) {
          const urlType = getUrlType(url);

          // Set URL information for this item
          resultItem.json.url_text_type = urlType;
          resultItem.json.url_text = url;
          break; // Only take the first valid URL
        }
      }
    }
  }

  // Always add the item to results (maintaining input/output count)
  results.push(resultItem);
}

return results;

/**
 * N8N Code Node to extract metadata from HTML content (Pure JavaScript).
 *
 * This code uses pure JavaScript string processing and regular expressions
 * to extract metadata from HTML content. No external modules or DOM APIs required.
 * 
 * FIXED: 
 * - Now processes ALL items in the input array, not just the first one
 * - Fixed undefined URL issue by ensuring all functions return null instead of undefined
 * - Enhanced regex patterns for better YouTube and other site compatibility
 * - Added better error handling and debugging
 * MODIFIED:
 * - Explicitly add 'text', 'created_at', and 'url_text' to the output JSON from the input item.
 */

/**
 * Helper function to decode HTML entities
 * @param {string} str - The string to decode
 * @returns {string} Decoded string
 */
const decodeHtmlEntities = (str) => {
  if (!str) return str;
  return str
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&amp;/g, '&')
    .replace(/&quot;/g, '"')
    .replace(/&#x27;/g, "'")
    .replace(/&#39;/g, "'")
    .replace(/&#x2F;/g, '/')
    .replace(/&#47;/g, '/')
    .replace(/\s+/g, ' ')
    .trim();
};

/**
 * Helper function to extract content from meta tags using regex
 * @param {string} html - The HTML content to search
 * @param {string} property - The property or name value to search for
 * @returns {string | null} The content of the meta tag, or null if not found
 */
const getMetaContent = (html, property) => {
  if (!html || !property) return null;

  // Escape special regex characters in property name
  const escapedProperty = property.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');

  // Try different patterns for meta tags with property attribute
  const propertyPatterns = [
    // Standard: <meta property="..." content="...">
    new RegExp(`<meta[^>]+property=["']${escapedProperty}["'][^>]*content=["']([^"']*?)["'][^>]*>`, 'i'),
    // Reversed: <meta content="..." property="...">
    new RegExp(`<meta[^>]+content=["']([^"']*?)["'][^>]*property=["']${escapedProperty}["'][^>]*>`, 'i'),
    // Without quotes: <meta property=... content=...>
    new RegExp(`<meta[^>]+property=${escapedProperty}[^>]*content=["']([^"']*?)["'][^>]*>`, 'i'),
  ];

  // Try different patterns for meta tags with name attribute
  const namePatterns = [
    // Standard: <meta name="..." content="...">
    new RegExp(`<meta[^>]+name=["']${escapedProperty}["'][^>]*content=["']([^"']*?)["'][^>]*>`, 'i'),
    // Reversed: <meta content="..." name="...">
    new RegExp(`<meta[^>]+content=["']([^"']*?)["'][^>]*name=["']${escapedProperty}["'][^>]*>`, 'i'),
    // Without quotes: <meta name=... content=...>
    new RegExp(`<meta[^>]+name=${escapedProperty}[^>]*content=["']([^"']*?)["'][^>]*>`, 'i'),
  ];

  // Try all patterns
  const allPatterns = [...propertyPatterns, ...namePatterns];

  for (const regex of allPatterns) {
    const match = html.match(regex);
    if (match && match[1]) {
      return decodeHtmlEntities(match[1]) || null;
    }
  }

  return null;
};

/**
 * Helper function to extract title from <title> tag
 * @param {string} html - The HTML content to search
 * @returns {string | null} The title text, or null if not found
 */
const getTitleContent = (html) => {
  if (!html) return null;

  const regex = /<title[^>]*>(.*?)<\/title>/is;
  const match = html.match(regex);
  if (match && match[1]) {
    return decodeHtmlEntities(match[1]) || null;
  }
  return null;
};

/**
 * Helper function to extract canonical URL from link tag
 * @param {string} html - The HTML content to search
 * @returns {string | null} The canonical URL, or null if not found
 */
const getCanonicalUrl = (html) => {
  if (!html) return null;

  const patterns = [
    // Standard: <link rel="canonical" href="...">
    /<link[^>]+rel=["']canonical["'][^>]*href=["']([^"']*?)["'][^>]*>/i,
    // Reversed: <link href="..." rel="canonical">
    /<link[^>]+href=["']([^"']*?)["'][^>]*rel=["']canonical["'][^>]*>/i,
    // Without quotes
    /<link[^>]+rel=canonical[^>]*href=["']([^"']*?)["'][^>]*>/i,
  ];

  for (const regex of patterns) {
    const match = html.match(regex);
    if (match && match[1]) {
      return match[1] || null;
    }
  }

  return null;
};

/**
 * Helper function to extract URL from window.location or other JavaScript variables
 * @param {string} html - The HTML content to search
 * @returns {string | null} The URL, or null if not found
 */
const getJavaScriptUrl = (html) => {
  if (!html) return null;

  // Try to find YouTube's canonical URL in script tags
  const youtubePatterns = [
    /"canonicalBaseUrl":"([^"]+)"/,
    /"webPageUrl":"([^"]+)"/,
    /window\.location\.href\s*=\s*["']([^"']+)["']/,
    /canonical_url["']\s*:\s*["']([^"']+)["']/,
  ];

  for (const regex of youtubePatterns) {
    const match = html.match(regex);
    if (match && match[1]) {
      // YouTube URLs might need to be constructed
      let url = match[1];
      if (url.startsWith('/watch')) {
        url = 'https://www.youtube.com' + url;
      }
      return url || null;
    }
  }

  return null;
};

/**
 * Process a single item to extract metadata
 * @param {object} item - Single item from the input array
 * @returns {object} Processed item with metadata
 */
const processItem = (item) => {
  // Ensure we have valid input
  if (!item || !item.json) {
    return { json: { metadata: { url: null, title: null, description: null, imageUrl: null } } };
  }

  const htmlContent = item.json.data;

  // If no HTML content, return empty metadata
  if (!htmlContent || typeof htmlContent !== 'string') {
    return { 
      json: {        
        metadata: { url: null, title: null, description: null, imageUrl: null },
        text: item.json.text,
        created_at: item.json.created_at,
        url_text: item.json.url_text,
      }
    };
  }

  // Extract metadata with fallback priorities
  let url = getMetaContent(htmlContent, 'og:url') || 
           getMetaContent(htmlContent, 'twitter:url') || 
           getCanonicalUrl(htmlContent) ||
           getJavaScriptUrl(htmlContent);

  // Ensure url is null instead of undefined
  url = url || null;

  let title = getMetaContent(htmlContent, 'og:title') || 
             getMetaContent(htmlContent, 'twitter:title') || 
             getTitleContent(htmlContent);

  // Clean up title - remove common suffixes like "- YouTube"
  if (title) {
    title = title.replace(/\s*-\s*YouTube\s*$/, '').trim() || title;
  }
  title = title || null;

  let description = getMetaContent(htmlContent, 'og:description') || 
                   getMetaContent(htmlContent, 'twitter:description') || 
                   getMetaContent(htmlContent, 'description');
  description = description || null;

  let imageUrl = getMetaContent(htmlContent, 'og:image') || 
                getMetaContent(htmlContent, 'twitter:image') ||
                getMetaContent(htmlContent, 'og:image:url');
  imageUrl = imageUrl || null;

  // Construct the metadata object - ensure all values are null instead of undefined
  const metadata = {
    url: url,
    title: title,
    description: description,
    imageUrl: imageUrl,
  };

  // Return the extracted metadata along with original data
  return {
    json: {      
      metadata: metadata,  // Add extracted metadata
      text: item.json.text,
      created_at: item.json.created_at,
      url_text: item.json.url_text,
    }
  };
};

// Ensure items exists and is an array
if (!items || !Array.isArray(items)) {
  return [{ json: { error: 'No valid input items found' } }];
}

// Process ALL items in the input array
const results = items.map(processItem);

// Return all processed results
return results;

// Transform YouTube API response to metadata format (robust version)
// MODIFIED:
// - Preserve original fields (text, created_at, url_text, etc.) even when the API response is invalid.
// - Cleaned up object creation to be more DRY.

const results = [];

for (const item of $input.all()) {
  const data = item.json;

  // Define a base object with the fields from the input that we want to preserve.
  // This ensures these fields are always included in the output.
  const baseJson = {
    text: item.json?.text,
    created_at: item.json?.created_at,        
    url_text: item.json?.url_text
  };

  // If the API response is abnormal, return placeholder metadata,
  // but ensure the original data fields are preserved.
  if (!data || !Array.isArray(data.items) || data.items.length === 0) {
    results.push({
      json: {
        ...baseJson,
        metadata: { title: null, description: null, imageUrl: null },
      },
    });
    continue;
  }

  // Extract metadata from the valid API response.
  const snippet = data.items[0]?.snippet ?? {};
  const title = snippet.title ?? null;
  const description = snippet.description ? snippet.description.slice(0, 500) : null;

  const thumbs = snippet.thumbnails ?? {};
  const thumbnailUrl =
    thumbs.maxres?.url ||
    thumbs.standard?.url ||
    thumbs.high?.url ||
    thumbs.medium?.url ||
    thumbs.default?.url ||
    null;

  // Push the final result, combining the preserved original fields
  // with the new metadata from YouTube.
  results.push({
    json: {
      ...baseJson,
      metadata: {
        title,
        description,
        imageUrl: thumbnailUrl,
      },
    },
  });
}

return results;

const REMOVE_RE = /\s*\(formerly\s+twitter\)\s*/i;

const clean = s => (s || '').replace(REMOVE_RE, '').trim() || null;

const results = [];

const isImageUrl = (url) => {
  if (!url || typeof url !== 'string') {
    return false;
  }
  return /\.(jpg|jpeg|png|gif|bmp|webp|svg)(?:\?.*)?$/i.test(url);
};

for (const item of $input.all()) {
  const json = item.json ?? {};
  let title = null, description = null, imageUrl = null;
  let text = null, created_at = null, url_text = null;

  // Check if this is a "data" type structure (alternate format)
  if (json.data && typeof json.data === 'object') {
    const data = json.data;
    title = clean(data.title);
    description = clean(data.description);
    imageUrl = data.image || data.logo || null;
    text = data.headline || data.title || null;
    created_at = json.timestamp || data.date || null;
    url_text = data.url || json.meta?.url || null;
  } else {
    // Original structure
    const meta = json.meta ?? {};
    const site = meta.site ?? {};
    text = json.text;
    url_text = json.url_text;
    created_at = json.created_at;

    if (isImageUrl(url_text)) {
      title = null;
      description = null;
      imageUrl = null;
    } else {
      title = clean(meta.title);
      const siteName = clean(site.name);
      const canonical = site.canonical ?? '';
      imageUrl = meta.image ?? null;

      if (siteName && canonical)      description = `${siteName} - ${canonical}`;
      else if (siteName)              description = siteName;
      else if (canonical)             description = canonical;

      description = clean(description);
    }
  }

  results.push({
    json: {
      text,
      created_at,
      url_text,
      metadata: { title, description, imageUrl }
    }
  });
}

return results;

// This code assumes 'items' is NOT globally available in your version of n8n
// Instead, use the correct way to access input items in n8n Code node
// which is via $input.all() or $input.item if working on a single item

