});

// FIXED: The function to extract the YouTube video ID has been made more robust
// to handle various URL formats (watch, youtu.be, embed, shorts).
// MODIFIED: Added support for YouTube Live URLs (e.g., /live/VIDEO_ID).

/**
 * Extracts the YouTube video ID from various URL formats.
 * @param {string} url - The URL to parse.
 * @returns {string|null} The YouTube video ID, or null if not found.
 */
function extractYouTubeId(url) {
  // Return null if the URL is not a valid string.
  if (!url || typeof url !== 'string') {
    return null;
  }

  // An array of regular expressions to match different YouTube URL formats.
  // The video ID is captured in the first group.
  const regexPatterns = [
    // Standard link: https://www.youtube.com/watch?v=VIDEO_ID
    /[?&]v=([^&?#]+)/,
    // Short link: https://youtu.be/VIDEO_ID
    /youtu\.be\/([^?#]+)/,
    // Embed link: https://www.youtube.com/embed/VIDEO_ID
    /\/embed\/([^?#]+)/,
    // Shorts link: https://www.youtube.com/shorts/VIDEO_ID
    /\/shorts\/([^?#]+)/,
    // Live link: https://www.youtube.com/live/VIDEO_ID
    /\/live\/([^?#]+)/
  ];

  // Iterate through the patterns and return the first match found.
  for (const regex of regexPatterns) {
    const match = url.match(regex);
    if (match && match[1]) {
      // The video ID is in the first capturing group.
      return match[1];
    }
  }

  // If no patterns match, return null.
  return null;
}


// Loop over input items and add a new field called 'youtube_vid' to the JSON of each one.
for (const item of $input.all()) {
  const urlToParse = item.json.url_text;
  item.json.youtube_vid = extractYouTubeId(urlToParse);
}

return $input.all();

