// Check if URL should have preview based on configured domains
function has_preview(url) {
  // Handle null/undefined/empty url  
  if (!url || typeof url !== 'string') return false;

  // Get the domains array from config
  const config = $('Redis').first();
  if (!config) return true; // Default to true if no config found

  const domains = config.json.cfg_domains_wo_preview;
  if (!domains || !Array.isArray(domains)) {
    return true; // Default to true if domains not configured properly
  }

  // Convert URL to lowercase once for performance
  const lowerUrl = url.toLowerCase();

  // Check if url contains any of the domains (no preview domains)
  for (const domain of domains) {
    if (domain && lowerUrl.includes(domain.toLowerCase())) {
      return false; // URL contains a no-preview domain
    }
  }

  return true; // URL doesn't contain any no-preview domains, so it has preview
}

// Process all items and add has_preview field
const items = $input.all();
for (const item of items) {
  if (item && item.json) {    
    item.json.has_preview = has_preview(item.json.url_text);
  }
}

return items;
